style.css:
/* FIND-A Sprint 발표 덱 — 참고 PDF의 디자인 언어를 재현한다.
   검정 배경 · 흰 텍스트 · 블루 액센트 · 좌상단 굵은 제목 + 얇은 구분선. */

@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@400;500;700;900&display=swap');

:root {
  --bg: #0A0A0A;
  --fg: #FFFFFF;
  --muted: #9CA3AF;
  --dim: #6B7280;
  --accent: #3B82F6;
  --accent-soft: #60A5FA;
  --card: #141414;
  --card-2: #1A1A1A;
  --line: #2A2A2A;
  --good: #34D399;
  --bad: #F87171;
  --slide-w: 1600px;
  --slide-h: 900px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  background: #050505;
  color: var(--fg);
  font-family: 'Noto Sans KR', 'Pretendard', 'Malgun Gothic', system-ui, sans-serif;
  -webkit-font-smoothing: antialiased;
  margin: 0;
}

/* 슬라이드는 1600x900 고정. 크기 맞춤은 deck-stage.js가 transform:scale로
   처리한다 — 반응형 재배치를 하지 않는 이유는 발표 판면이 설계한 그대로
   보여야 하기 때문이다. 여기서는 판면 '안'의 배치만 정한다. */
.slide {
  width: var(--slide-w);
  height: var(--slide-h);
  background: var(--bg);
  padding: 72px 88px 64px;
  overflow: hidden;
}

.slide-num {
  position: absolute; right: 40px; bottom: 28px;
  font-size: 16px; color: #3A3A3A; letter-spacing: .04em;
}

h1.title {
  font-size: 52px; font-weight: 900; letter-spacing: -.02em; line-height: 1.15;
}
.rule { height: 1px; background: var(--line); margin: 26px 0 40px; }

.lead { font-size: 25px; font-weight: 700; line-height: 1.5; }
.sub  { font-size: 19px; color: var(--muted); line-height: 1.65; font-weight: 400; }
.tiny { font-size: 16px; color: var(--dim); line-height: 1.6; }

.accent { color: var(--accent-soft); }
.good { color: var(--good); }
.bad { color: var(--bad); }
strong { font-weight: 700; }

/* --- 카드 --- */
.card {
  background: var(--card); border: 1px solid var(--line);
  border-radius: 14px; padding: 26px 30px;
}
.card.hi { border-color: var(--accent); background: #0E1626; }
.card h3 { font-size: 21px; font-weight: 700; margin-bottom: 12px; }
.card p  { font-size: 17px; color: var(--muted); line-height: 1.6; }

.grid { display: grid; gap: 22px; }
.g2 { grid-template-columns: 1fr 1fr; }
.g3 { grid-template-columns: repeat(3, 1fr); }
.g4 { grid-template-columns: repeat(4, 1fr); }

/* --- 큰 통계 --- */
.stats { display: flex; align-items: stretch; gap: 0; }
.stat { flex: 1; padding: 0 40px; }
.stat:first-child { padding-left: 0; }
.stat + .stat { border-left: 1px solid var(--line); }
.stat .v { font-size: 54px; font-weight: 900; letter-spacing: -.02em; line-height: 1.1; }
.stat .v.sm { font-size: 40px; }
.stat .k { font-size: 16px; color: var(--dim); margin-top: 10px; }

/* --- 단계 흐름 (01 → 02 → 03) --- */
.flow { display: flex; align-items: stretch; gap: 16px; }
.step { flex: 1; background: var(--card); border: 1px solid var(--line);
        border-radius: 14px; padding: 22px 24px; }
.step.hi { border-color: var(--accent); background: #0E1626; }
.step .n { font-size: 16px; font-weight: 700; color: var(--accent); letter-spacing: .1em; }
.step h4 { font-size: 20px; font-weight: 700; margin: 8px 0 10px; }
.step p { font-size: 16px; color: var(--muted); line-height: 1.55; }
.arrow { align-self: center; color: var(--accent); font-size: 26px; flex: none; }

/* --- 표 --- */
table { width: 100%; border-collapse: collapse; }
th, td { text-align: left; padding: 13px 16px; font-size: 18px; }
th { font-size: 16px; color: var(--dim); font-weight: 500;
     border-bottom: 1px solid var(--line); letter-spacing: .02em; }
td { border-bottom: 1px solid #1C1C1C; }
tbody tr:last-child td { border-bottom: none; }
td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }
tr.hl td { background: #0E1626; font-weight: 700; }
tr.hl td:first-child { border-left: 2px solid var(--accent); }
tr.dim td { color: var(--dim); }

/* 표가 두 개 이상 들어가 판면을 넘기는 슬라이드용. 글자 크기는 그대로 두고
   행 간격만 조인다 — 발표장 뒷줄에서 읽혀야 하므로 폰트를 줄이면 안 된다. */
.slide.tight th, .slide.tight td { padding: 9px 14px; }
.slide.tight .card { padding: 20px 24px; }
.slide.tight ul.bul li { margin-bottom: 10px; }

/* --- 목록 --- */
ul.bul { list-style: none; }
ul.bul li { position: relative; padding-left: 22px; margin-bottom: 15px;
            font-size: 19px; color: var(--muted); line-height: 1.6; }
ul.bul li::before { content: ''; position: absolute; left: 0; top: 11px;
            width: 6px; height: 6px; border-radius: 50%; background: var(--accent); }
ul.bul li b { color: var(--fg); font-weight: 700; }

/* --- 배지 --- */
.badge { display: inline-block; font-size: 16px; font-weight: 700;
         padding: 5px 12px; border-radius: 999px; letter-spacing: .02em; }
.badge.b { background: rgba(59,130,246,.16); color: var(--accent-soft); }
.badge.g { background: rgba(52,211,153,.14); color: var(--good); }
.badge.r { background: rgba(248,113,113,.14); color: var(--bad); }

/* --- 이미지 --- */
img.fig { width: 100%; height: 100%; object-fit: contain;
          background: #fff; border-radius: 10px; }

.eyebrow { font-size: 16px; font-weight: 700; color: var(--accent);
           letter-spacing: .12em; margin-bottom: 14px; }

/* 인쇄(PDF 내보내기) 규칙은 deck-stage.js가 갖고 있다. 여기에 또 두면
   두 벌이 어긋날 때 어느 쪽이 이기는지 알 수 없게 된다. */

deck-stage.js:
/* deck-stage — 고정 판면 슬라이드를 어떤 화면에도 맞추는 무대.
 *
 * 계약:
 *   <deck-stage width="1600" height="900">
 *     <section data-label="표지"> ... </section>
 *     ...
 *   </deck-stage>
 *
 * 하는 일
 *   - 레터박스 스케일링: 슬라이드는 항상 width×height로 그려지고 transform:scale로만
 *     맞춘다. 반응형 재배치를 하지 않는 이유는, 발표 자료의 판면은 설계된 그대로
 *     보여야 하기 때문이다 — 화면이 좁다고 표가 접히면 발표가 망가진다.
 *   - 키보드(←/→/Space/Home/End)·클릭·스와이프 이동
 *   - 현재 장을 URL 해시(#3)에 유지해 새로고침·링크 공유에도 위치가 남는다
 *   - 인쇄 시 한 장당 한 페이지 (PDF 내보내기)
 *
 * 조작부는 스케일되는 요소 **바깥**에 둔다. 안에 두면 축소 배율만큼 같이 작아져
 * 작은 화면일수록 누르기 어려워진다.
 */
(function () {
  "use strict";

  var CSS = `
deck-stage{position:fixed;inset:0;display:block;background:#050505;overflow:hidden}
deck-stage > section{
  position:absolute;left:0;top:0;transform-origin:top left;
  display:none;overflow:hidden;
}
deck-stage > section[data-active]{display:block}
.ds-bar{
  position:fixed;right:20px;bottom:18px;z-index:9;
  display:flex;align-items:center;gap:6px;
  font:500 13px/1 'Noto Sans KR',system-ui,sans-serif;color:#8A8A8A;
  background:rgba(20,20,20,.82);border:1px solid #2A2A2A;border-radius:999px;
  padding:6px 8px;backdrop-filter:blur(6px);opacity:.25;transition:opacity .18s;
}
.ds-bar:hover{opacity:1}
.ds-bar button{
  all:unset;cursor:pointer;padding:5px 10px;border-radius:999px;
  color:#CFCFCF;font:inherit;
}
.ds-bar button:hover{background:#262626;color:#fff}
.ds-bar button[disabled]{opacity:.3;cursor:default}
.ds-bar .ds-pos{padding:0 8px;font-variant-numeric:tabular-nums;letter-spacing:.02em}

@media print{
  @page{size:landscape;margin:0}
  html,body{background:#fff !important}
  deck-stage{position:static;overflow:visible;background:none}
  deck-stage > section{
    position:relative !important;display:block !important;
    transform:none !important;break-after:page;page-break-after:always;
  }
  deck-stage > section:last-child{break-after:auto;page-break-after:auto}
  .ds-bar{display:none !important}
}
`;

  function injectCss() {
    if (document.getElementById("ds-style")) return;
    var s = document.createElement("style");
    s.id = "ds-style";
    s.textContent = CSS;
    document.head.appendChild(s);
  }

  class DeckStage extends HTMLElement {
    connectedCallback() {
      if (this._ready) return;

      // connectedCallback은 여는 태그가 파싱되는 순간 불린다 — 이 스크립트가
      // <head>에 있으면 자식 <section>이 아직 하나도 없다. 실제로 그래서
      // 슬라이드를 0개로 읽고 화면이 비었다. 문서 파싱이 끝난 뒤에 시작한다.
      if (document.readyState === "loading") {
        var self = this;
        document.addEventListener("DOMContentLoaded", function () {
          self._init();
        }, { once: true });
        return;
      }
      this._init();
    }

    _init() {
      if (this._ready) return;
      this._ready = true;
      injectCss();

      this.W = +this.getAttribute("width") || 1600;
      this.H = +this.getAttribute("height") || 900;
      this.slides = Array.from(this.children).filter(function (el) {
        return el.tagName === "SECTION";
      });
      this.slides.forEach(function (el, i) {
        el.style.width = this.W + "px";
        el.style.height = this.H + "px";
        el.setAttribute("data-index", i + 1);
      }, this);

      this._buildBar();
      this._bind();
      this.go(this._fromHash(), true);
      this._fit();
    }

    _fromHash() {
      var n = parseInt((location.hash || "").replace("#", ""), 10);
      return isFinite(n) ? n : 1;
    }

    _buildBar() {
      var bar = document.createElement("div");
      bar.className = "ds-bar";
      bar.innerHTML =
        '<button data-ds="prev" aria-label="이전 슬라이드">←</button>' +
        '<span class="ds-pos"></span>' +
        '<button data-ds="next" aria-label="다음 슬라이드">→</button>' +
        '<button data-ds="print" aria-label="PDF로 인쇄">PDF</button>';
      document.body.appendChild(bar);
      this.bar = bar;

      var self = this;
      bar.addEventListener("click", function (e) {
        var b = e.target.closest("button");
        if (!b) return;
        var a = b.getAttribute("data-ds");
        if (a === "prev") self.go(self.i - 1);
        else if (a === "next") self.go(self.i + 1);
        else if (a === "print") window.print();
      });
    }

    _bind() {
      var self = this;
      addEventListener("resize", function () { self._fit(); });
      addEventListener("hashchange", function () { self.go(self._fromHash(), true); });

      addEventListener("keydown", function (e) {
        if (e.metaKey || e.ctrlKey || e.altKey) return;
        var k = e.key;
        if (k === "ArrowRight" || k === "PageDown" || k === " ") { self.go(self.i + 1); e.preventDefault(); }
        else if (k === "ArrowLeft" || k === "PageUp") { self.go(self.i - 1); e.preventDefault(); }
        else if (k === "Home") { self.go(1); e.preventDefault(); }
        else if (k === "End") { self.go(self.slides.length); e.preventDefault(); }
      });

      // 클릭 이동: 오른쪽 3분의 1은 다음, 왼쪽 3분의 1은 이전.
      // 가운데를 비워두는 이유는 표·본문을 드래그로 선택할 여지를 남기기 위해서다.
      this.addEventListener("click", function (e) {
        if (e.target.closest("a,button")) return;
        var x = e.clientX / innerWidth;
        if (x > 0.66) self.go(self.i + 1);
        else if (x < 0.34) self.go(self.i - 1);
      });

      var x0 = null;
      this.addEventListener("touchstart", function (e) { x0 = e.touches[0].clientX; }, { passive: true });
      this.addEventListener("touchend", function (e) {
        if (x0 === null) return;
        var dx = e.changedTouches[0].clientX - x0;
        if (Math.abs(dx) > 45) self.go(self.i + (dx < 0 ? 1 : -1));
        x0 = null;
      }, { passive: true });
    }

    _fit() {
      // 화면 안에 판면을 통째로 넣고 남는 여백은 위아래(또는 좌우)로 나눈다.
      var s = Math.min(innerWidth / this.W, innerHeight / this.H);
      var ox = (innerWidth - this.W * s) / 2;
      var oy = (innerHeight - this.H * s) / 2;
      this.slides.forEach(function (el) {
        el.style.transform = "translate(" + ox + "px," + oy + "px) scale(" + s + ")";
      });
    }

    go(n, silent) {
      var total = this.slides.length;
      n = Math.max(1, Math.min(total, n || 1));
      if (n === this.i) return;
      this.i = n;
      this.slides.forEach(function (el, k) {
        if (k === n - 1) el.setAttribute("data-active", "");
        else el.removeAttribute("data-active");
      });
      var pos = this.bar.querySelector(".ds-pos");
      if (pos) pos.textContent = n + " / " + total;
      this.bar.querySelector('[data-ds="prev"]').disabled = n === 1;
      this.bar.querySelector('[data-ds="next"]').disabled = n === total;
      if (!silent) history.replaceState(null, "", "#" + n);
      this._fit();
    }
  }

  if (!customElements.get("deck-stage")) {
    customElements.define("deck-stage", DeckStage);
  }
})();
